class Solution { public boolean isPrintable(int[][] grid){int colors=61,rows=grid.length,cols=grid[0].length;int[] minRow=new int[colors],maxRow=new int[colors],minCol=new int[colors],maxCol=new int[colors];Arrays.fill(minRow,rows);Arrays.fill(minCol,cols);boolean[] present=new boolean[colors];for(int row=0;row<rows;row++)for(int col=0;col<cols;col++){int color=grid[row][col];present[color]=true;minRow[color]=Math.min(minRow[color],row);maxRow[color]=Math.max(maxRow[color],row);minCol[color]=Math.min(minCol[color],col);maxCol[color]=Math.max(maxCol[color],col);}boolean[][] edge=new boolean[colors][colors];int[] indegree=new int[colors];int total=0;for(int color=1;color<colors;color++)if(present[color]){total++;for(int row=minRow[color];row<=maxRow[color];row++)for(int col=minCol[color];col<=maxCol[color];col++){int other=grid[row][col];if(other!=color&&!edge[color][other]){edge[color][other]=true;indegree[other]++;}}}Queue<Integer> queue=new ArrayDeque<>();for(int color=1;color<colors;color++)if(present[color]&&indegree[color]==0)queue.offer(color);int processed=0;while(!queue.isEmpty()){int color=queue.poll();processed++;for(int other=1;other<colors;other++)if(edge[color][other]&&--indegree[other]==0)queue.offer(other);}return processed==total;} }
